android.extraProguardRules:
# MapLibre native bindings (JNI + reflection)
-keep class org.maplibre.** { *; }
-dontwarn org.maplibre.**
# Keep JS engine exception names readable in crash reports
-keepattributes SourceFile,LineNumberTable
-renamesourcefileattribute SourceFile

# --- R8 optimization is ON (proguard-android-optimize.txt) ---
# Optimization passes inline methods and merge classes, which breaks anything
# the runtime resolves by NAME rather than by reference: JNI natives, the
# @DoNotStrip members React Native and Fresco call from C++, and the Expo
# module registry. Shrinking alone never touched these; optimization does.
-keepclasseswithmembernames,includedescriptorclasses class * { native <methods>; }
-keep @com.facebook.proguard.annotations.DoNotStrip class * { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.common.internal.DoNotStrip *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.hermes.** { *; }
# Expo looks modules and their exported functions up by name at runtime.
-keep class * extends expo.modules.kotlin.modules.Module { *; }
-keep class expo.modules.** { *; }
-dontwarn expo.modules.**
